// ==========================================
// ESP8266 NodeMCU: เชื่อมต่อ Wi-Fi และเปิด-ปิดขา D1
// แก้ไขชื่อ Wi-Fi, รหัสผ่าน และเลขขา OUTPUT_PIN ด้านล่างได้ทันที
// ==========================================
#include <ESP8266WiFi.h>

#define OUTPUT_PIN  D1   // ขาควบคุมโหลดหรือรีเลย์ (เช่น ขา D1 หรือ D2)
#define ONBOARD_LED D4   // LED บนบอร์ด NodeMCU (Active LOW: LOW=ติด, HIGH=ดับ)

const char* ssid     = "YOUR_WIFI_NAME";     // ใส่ชื่อ Wi-Fi ของคุณ
const char* password = "YOUR_WIFI_PASSWORD"; // ใส่รหัสผ่าน Wi-Fi ของคุณ

void setup() {
  Serial.begin(115200);
  pinMode(OUTPUT_PIN, OUTPUT);
  pinMode(ONBOARD_LED, OUTPUT);
  digitalWrite(OUTPUT_PIN, LOW);
  digitalWrite(ONBOARD_LED, HIGH); // ปิด LED ก่อน

  Serial.println("\n--- NodeMCU Wi-Fi Initializing ---");
  Serial.print("Connecting to: ");
  Serial.println(ssid);

  WiFi.mode(WIFI_STA);
  WiFi.begin(ssid, password);

  while (WiFi.status() != WL_CONNECTED) {
    delay(400);
    Serial.print(".");
    digitalWrite(ONBOARD_LED, !digitalRead(ONBOARD_LED)); // กะพริบไฟขณะรอต่อ
  }

  digitalWrite(ONBOARD_LED, LOW); // ติดค้างเมื่อต่อ Wi-Fi สำเร็จ
  Serial.println("\n>>> NodeMCU Connected! <<<");
  Serial.print("IP Address: ");
  Serial.println(WiFi.localIP());
}

void loop() {
  // กะพริบทดสอบขา OUTPUT_PIN ทุกๆ 2 วินาที
  digitalWrite(OUTPUT_PIN, HIGH);
  delay(2000);
  digitalWrite(OUTPUT_PIN, LOW);
  delay(2000);
}
